/// answer. Blocking.
fn start_docker(on_line: &mut dyn FnMut(String)) -> Result<()> {
    let mut command = match Platform::current() {
        Platform::MacOs => {
            let mut open = crate::process::command("open");
            open.args(["-a", "Docker"]);
            open
        }
        Platform::Windows => {
            let mut start = crate::process::command("cmd");
            start.args(["/C", "start", "", "Docker Desktop"]);
            start
        }
        Platform::Linux => {
            let mut start = crate::process::command("systemctl");
            start.args(["--user", "start", "docker-desktop"]);
            start
        }
    };
    on_line("Starting Docker Desktop…".into());
    command.stdin(Stdio::null()).status_logged().context("could not start Docker Desktop")?;
    let until = std::time::Instant::now() + std::time::Duration::from_secs(120);
    loop {
        match access_of(Runtime::Docker) {
            Ok(()) => {
                on_line("Docker Desktop is running.".into());
                return Ok(());
            }
            Err(why) if std::time::Instant::now() >= until => {
                bail!("Docker Desktop didn't start: {why}")
            }
            Err(_) => std::thread::sleep(std::time::Duration::from_secs(2)),
        }
    }
}

