/// A container, image, or volume the application made, in `runtime`.
#[derive(Clone, Debug, PartialEq)]
pub struct Resource {
    pub runtime: Runtime,
    pub kind: ResourceKind,
    /// What deletes it: its id, or a volume's name.
    pub id: String,
    pub name: String,
    /// What it is for, as "Default image" or "Codex login".
    pub purpose: String,
