impl Resource {
    /// What deleting it loses, as its confirmation says.
    pub fn loses(&self) -> String {
        match self.kind {
            ResourceKind::Container => format!(
                "{}: the task or question running in it is stopped, as cancelling stops it.",
                self.name
            ),
            ResourceKind::Image => format!("{}: it is built again when next needed.", self.name),
            ResourceKind::Volume => format!(
                "{}: the harness must log in again.",
                self.name
            ),
        }
    }
}

/// Reads a size as a runtime prints it, "1.23 GB", "512MB", or "0B (virtual
/// 1.2GB)", in bytes.
fn bytes_in(printed: &str) -> Option<u64> {
    let first = printed.split('(').next()?.trim().replace(' ', "");
    let split = first.find(|c: char| c.is_ascii_alphabetic())?;
    let (number, unit) = first.split_at(split);
    let number: f64 = number.parse().ok()?;
    let scale = match unit.to_ascii_lowercase().as_str() {
        "b" => 1.,
        "kb" | "kib" => 1e3,
        "mb" | "mib" => 1e6,
        "gb" | "gib" => 1e9,
        "tb" | "tib" => 1e12,
        _ => return None,
    };
    Some((number * scale) as u64)
}

/// A size as shown, "1.2 GB".
pub fn size_label(bytes: u64) -> String {
    let bytes = bytes as f64;
    for (scale, unit) in [(1e12, "TB"), (1e9, "GB"), (1e6, "MB"), (1e3, "kB")] {
        if bytes >= scale {
            return format!("{:.1} {unit}", bytes / scale);
        }
    }
    format!("{bytes:.0} B")
}

/// How long ago `created`, as a runtime gives it, "2026-10-12 10:00:00
/// +0700 +07", was, as "3 days ago".
pub fn age_label(created: &str) -> Option<String> {
    let mut parts = created.split_whitespace();
    let (date, time, zone) = (parts.next()?, parts.next()?, parts.next()?);
    let time = time.split('.').next()?;
    let at = chrono::DateTime::parse_from_str(&format!("{date} {time} {zone}"), "%Y-%m-%d %H:%M:%S %z").ok()?;
    let ago = chrono::Utc::now().signed_duration_since(at);
    let (n, unit) = if ago.num_days() >= 1 {
        (ago.num_days(), "day")
    } else if ago.num_hours() >= 1 {
        (ago.num_hours(), "hour")
    } else if ago.num_minutes() >= 1 {
        (ago.num_minutes(), "minute")
    } else {
        return Some("just now".into());
    };
    Some(format!("{n} {unit}{} ago", if n == 1 { "" } else { "s" }))
}

/// Whether `name`, as a runtime lists it, is one the application gave:
/// beginning `suspense-`, wherever its registry says it is.
fn named_ours(name: &str) -> bool {
    name.rsplit('/').next().is_some_and(|name| name.starts_with("suspense-"))
}

/// What an image of the application's named `repository` is for.
fn image_purpose(repository: &str) -> String {
    let name = repository.rsplit('/').next().unwrap_or(repository);
    match name.strip_prefix("suspense-project-") {
        Some(key) => {
            // Its key is the project's folder and a hash of where it is.
            let project = key.rsplit_once('-').map_or(key, |(project, _)| project);
            format!("Project image · {project}")
        }
        None => "Default image".into(),
    }
}

/// What a volume of the application's named `name` is for.
fn volume_purpose(name: &str) -> String {
    Agent::RUNNABLE
        .into_iter()
        .find(|agent| home_volume(*agent) == name)
        .map_or_else(|| "Volume".into(), |agent| format!("{} login", agent.label()))
}

/// What a container of the application's named `name`, `status` as the
/// runtime says, is for.
fn container_purpose(name: &str, status: &str) -> String {
    let what = if name.starts_with("suspense-spec-") {
        "Spec task"
    } else if name.starts_with("suspense-questions-") {
        "Question"
    } else {
        "Run"
    };
    if status.starts_with("Up") {
        format!("Running: {what}")
    } else {
        format!("Left by a {} that was cut off", what.to_lowercase())
    }
}

/// Runs `runtime` with `args`, giving what it printed, one line each.
/// Blocking.
fn lines_of(runtime: Runtime, args: &[&str]) -> Result<Vec<String>> {
    let output = runtime_command(runtime)
        .args(args)
        .stdin(Stdio::null())
        .output_logged()
        .with_context(|| format!("could not run {}", runtime.command()))?;
    if !output.status.success() {
        bail!(
            "{} couldn't list its resources: {}",
            runtime.label(),
            String::from_utf8_lossy(&output.stderr).trim()
        );
    }
    Ok(String::from_utf8_lossy(&output.stdout)
        .lines()
        .filter(|line| !line.trim().is_empty())
        .map(str::to_string)
        .collect())
}

/// Everything of the application's `runtime` holds, found by its label or
/// its name: containers, then images, then volumes. Blocking.
pub fn resources(runtime: Runtime) -> Result<Vec<Resource>> {
    let label = format!("label={LABEL}");
    let mut found = Vec::new();
    for line in lines_of(
        runtime,
        &[
            "ps",
            "-a",
            "--size",
            "--filter",
            &label,
            "--format",
            "{{.ID}}\\t{{.Names}}\\t{{.Status}}\\t{{.Size}}\\t{{.CreatedAt}}",
        ],
    )? {
        let fields: Vec<&str> = line.split('\\t').collect();
        let [id, name, status, size, created] = fields[..] else {
            continue;
        };
        let name = name.trim_matches(|c| c == '[' || c == ']').to_string();
        found.push(Resource {
            runtime,
            kind: ResourceKind::Container,
            id: id.to_string(),
            purpose: container_purpose(&name, status),
            name,
            size: bytes_in(size),
            created: Some(created.to_string()),
        });
    }
    // Images by name, as those made before they were labelled are found
    // too; each once, whatever its tags.
    for line in lines_of(
        runtime,
        &[
            "images",
            "--format",
            "{{.ID}}\\t{{.Repository}}\\t{{.Tag}}\\t{{.Size}}\\t{{.CreatedAt}}",
        ],
    )? {
        let fields: Vec<&str> = line.split('\\t').collect();
        let [id, repository, tag, size, created] = fields[..] else {
            continue;
        };
        if !named_ours(repository) || found.iter().any(|known: &Resource| known.id == id) {
            continue;
        }
        found.push(Resource {
            runtime,
            kind: ResourceKind::Image,
            id: id.to_string(),
            name: format!("{repository}:{tag}"),
            purpose: image_purpose(repository),
            size: bytes_in(size),
            created: Some(created.to_string()),
        });
    }
    for name in lines_of(runtime, &["volume", "ls", "--format", "{{.Name}}"])? {
        let name = name.trim().to_string();
        if !named_ours(&name) {
            continue;
        }
        let created = lines_of(runtime, &["volume", "inspect", "--format", "{{.CreatedAt}}", &name])
            .ok()
            .and_then(|lines| lines.into_iter().next());
        found.push(Resource {
            runtime,
            kind: ResourceKind::Volume,
            id: name.clone(),
            purpose: volume_purpose(&name),
            name,
            size: None,
            created,
        });
    }
    Ok(found)
}

/// Deletes `resource` from its runtime: a container stopped and removed, an
/// image or a volume removed. Never anything without the application's
/// label or name. Blocking.
pub fn delete(resource: &Resource) -> Result<()> {
    let args: Vec<&str> = match resource.kind {
        ResourceKind::Container => vec!["rm", "-f", &resource.id],
        ResourceKind::Image => vec!["rmi", "-f", &resource.id],
        ResourceKind::Volume => vec!["volume", "rm", "-f", &resource.id],
    };
    if resource.kind != ResourceKind::Image && !named_ours(&resource.name) {
        bail!("{} isn't the application's", resource.name);
    }
    let output = runtime_command(resource.runtime)
        .args(&args)
        .stdin(Stdio::null())
        .output_logged()
        .with_context(|| format!("could not run {}", resource.runtime.command()))?;
    if !output.status.success() {
        bail!("{}", String::from_utf8_lossy(&output.stderr).trim());
    }
    Ok(())
}

