        let Some(containers) = &self.containers else {
            return div().text_color(muted).child("Checking the container runtimes…").into_any_element();
        };
        let radios = RuntimeChoice::ALL.into_iter().map(|choice| {
            let note = (choice == RuntimeChoice::Automatic).then(|| match containers.picked {
                Some(runtime) if containers.choice == RuntimeChoice::Automatic => {
                    format!("Using {}", runtime.label())
                }
                None if containers.choice == RuntimeChoice::Automatic => {
                    "Neither is available".to_string()
                }
                _ => String::new(),
            });
            h_flex()
                .gap_2()
                .child(
                    Radio::new(SharedString::from(format!("settings-runtime-{}", choice.label().to_lowercase())))
                        .label(choice.label())
                        .checked(containers.choice == choice)
                        .on_click(cx.listener(move |this, _: &bool, _, cx| this.pick_runtime(choice, cx))),
                )
                .children(note.filter(|note| !note.is_empty()).map(|note| {
                    div().text_sm().text_color(muted).child(note)
                }))
        });
        let rows = containers.runtimes.iter().map(|(runtime, state, access)| {
            let runtime = *runtime;
            let id = runtime.command();
            let status: AnyElement = match state {
                PodmanState::Missing => h_flex()
                    .gap_2()
                    .child(div().text_color(muted).child("Not installed"))
                    .child(
                        Button::new(SharedString::from(format!("settings-install-{id}")))
                            .small()
                            .label(format!("Install {}", runtime.label()))
                            .on_click(move |_, _, cx| cx.open_url(runtime.install_url(platform))),
                    )
                    .into_any_element(),
                PodmanState::Ready(version) => match access {
                    None => div()
                        .child(match platform.has_machine() {
                            true => format!("{version} · {} running", runtime.machine_label()),
                            false => version.clone(),
                        })
                        .into_any_element(),
                    Some(said) => div()
                        .text_color(cx.theme().danger)
                        .child(format!("{version}, but it can't run a container: {said}"))
                        .into_any_element(),
                },
                state => {
                    let action = match (runtime, state) {
                        (crate::container::Runtime::Docker, _) => MachineAction::StartDocker,
                        (_, PodmanState::NoMachine) => MachineAction::SetUp,
                        _ => MachineAction::Start,
                    };
                    h_flex()
                        .gap_2()
                        .child(div().text_color(muted).child(format!("{} isn't running", runtime.machine_label())))
                        .child(
                            Button::new(SharedString::from(format!("settings-machine-{id}")))
                                .small()
                                .label(action.label())
                                .on_click(cx.listener(move |this, _, _, cx| {
                                    let project_dir = ProjectDirectory::get(cx);
                                    let run = cx.background_spawn(async move {
                                        crate::container::run_machine_action(action, &mut |_| {}).ok();
                                    });
                                    this._containers_read = cx.spawn(async move |this, cx| {
                                        run.await;
                                        this.update(cx, |this, cx| this.read_containers(project_dir, cx))
                                            .ok();
                                    });
                                })),
                        )
                        .into_any_element()
                }
            };
            h_flex()
                .gap_2()
                .text_sm()
                .child(div().w(px(120.)).child(runtime.label()))
                .child(status)
        });
        v_flex()
            .id("settings-runtime")
            .gap_2()
            .child(div().font_semibold().child("Runtime"))
            .child(v_flex().gap_1p5().children(radios))
            .child(v_flex().gap_1().pt_1().children(rows))
            .into_any_element()
    }

    /// Uses `choice` from the next run on, kept for the user.
    fn pick_runtime(&mut self, choice: RuntimeChoice, cx: &mut Context<Self>) {
        choice.save().ok();
        if let Some(containers) = &mut self.containers {
            containers.choice = choice;
        }
        self.read_containers(ProjectDirectory::get(cx), cx);
        cx.notify();
    }

    /// "Resources": what the application made in each installed runtime,
    /// each with Delete, and Delete all for each runtime and for both.
    fn render_resources(&self, cx: &mut Context<Self>) -> AnyElement {
        use crate::container::ResourceKind;
        let muted = cx.theme().muted_foreground;
        let danger = cx.theme().danger;
        let listed: Vec<Resource> = self
            .containers
            .iter()
            .flat_map(|containers| &containers.resources)
            .filter_map(|(_, found)| found.as_ref().ok())
            .flatten()
            .cloned()
            .collect();
        let heading = h_flex()
            .gap_2()
            .child(div().flex_1().font_semibold().child("Resources"))
            .child(
                Button::new("settings-resources-refresh")
                    .ghost()
                    .small()
                    .icon(IconName::RefreshCw)
                    .label("Refresh")
                    .on_click(cx.listener(|this, _, _, cx| {
                        this.read_containers(ProjectDirectory::get(cx), cx)
                    })),
            )
            .when(!listed.is_empty(), |row| {
                let all = listed.clone();
                row.child(
                    Button::new("settings-resources-delete-all")
                        .ghost()
                        .small()
                        .label("Delete all")
                        .on_click(cx.listener(move |this, _, window, cx| {
                            this.confirm_delete(all.clone(), window, cx)
                        })),
                )
            });
        let groups = self.containers.iter().flat_map(|containers| &containers.resources).map(|(runtime, found)| {
            let runtime = *runtime;
            let id = runtime.command();
            let mut group = v_flex().gap_1();
            let total: u64 = found
                .as_ref()
                .map(|found| found.iter().filter_map(|resource| resource.size).sum())
                .unwrap_or(0);
            let mine: Vec<Resource> = found.as_ref().cloned().unwrap_or_default();
            group = group.child(
                h_flex()
                    .gap_2()
                    .child(div().text_sm().font_medium().child(runtime.label()))
                    .child(div().flex_1().text_sm().text_color(muted).child(crate::container::size_label(total)))
                    .when(!mine.is_empty(), |row| {
                        row.child(
                            Button::new(SharedString::from(format!("settings-resources-delete-all-{id}")))
                                .ghost()
                                .xsmall()
                                .label("Delete all")
                                .on_click(cx.listener(move |this, _, window, cx| {
                                    this.confirm_delete(mine.clone(), window, cx)
                                })),
                        )
                    }),
            );
            match found {
                Err(why) => group.child(div().text_sm().text_color(danger).child(why.clone())),
                Ok(found) if found.is_empty() => {
                    group.child(div().text_sm().text_color(muted).child("Nothing here"))
                }
                Ok(found) => group.children(found.iter().enumerate().map(|(n, resource)| {
                    let key = (runtime, resource.id.clone());
                    let icon = match resource.kind {
                        ResourceKind::Container => IconName::Box,
                        ResourceKind::Image => IconName::Layers,
                        ResourceKind::Volume => IconName::HardDrive,
                    };
                    let deleting = self.deleting.contains(&key);
                    let error = self.delete_errors.get(&key).cloned();
                    let one = resource.clone();
                    gpui_kit::TestSupportExt::test_support(
                        v_flex().id(SharedString::from(format!("settings-resource-{id}-{n}"))),
                    )
                    .child(
                        h_flex()
                            .gap_2()
                            .text_sm()
                            .child(Icon::new(icon).xsmall().text_color(muted))
                            .child(div().min_w_0().truncate().child(resource.name.clone()))
                            .child(div().flex_1().min_w_0().truncate().text_color(muted).child(resource.purpose.clone()))
                            .children(resource.size.map(|size| {
                                div().text_color(muted).child(crate::container::size_label(size))
                            }))
                            .children(resource.created.as_deref().and_then(crate::container::age_label).map(|age| {
                                div().text_color(muted).child(age)
                            }))
                            .child(if deleting {
                                Spinner::new().small().into_any_element()
                            } else {
                                Button::new(SharedString::from(format!("settings-resource-delete-{id}-{n}")))
                                    .ghost()
                                    .xsmall()
                                    .label("Delete")
                                    .on_click(cx.listener(move |this, _, window, cx| {
                                        this.confirm_delete(vec![one.clone()], window, cx)
                                    }))
                                    .into_any_element()
                            }),
                    )
                    .children(error.map(|error| div().text_xs().text_color(danger).child(error)))
                })),
            }
        });
        v_flex()
            .id("settings-resources")
            .gap_2()
            .child(heading)
            .child(
                div()
                    .text_sm()
                    .text_color(muted)
                    .child("Everything Suspense made in each runtime: its containers, images, and volumes."),
            )
            .children(groups)
            .into_any_element()
    }

    /// Asks before deleting `resources`, saying what each loses.
    fn confirm_delete(&mut self, resources: Vec<Resource>, window: &mut Window, cx: &mut Context<Self>) {
        if resources.is_empty() {
            return;
        }
        let title: SharedString = match &resources[..] {
            [one] => format!("Delete {}?", one.name).into(),
            many => format!("Delete these {} resources?", many.len()).into(),
        };
        let description: SharedString = resources
            .iter()
            .map(Resource::loses)
            .collect::<Vec<_>>()
            .join("\\n")
            .into();
        let this = cx.entity().downgrade();
        window.open_alert_dialog(cx, move |alert, _, _| {
            let (this, resources) = (this.clone(), resources.clone());
            alert
                .title(title.clone())
                .description(description.clone())
                .button_props(
                    gpui_kit::component::dialog::DialogButtonProps::default()
                        .ok_text("Delete")
                        .ok_variant(gpui_kit::component::button::ButtonVariant::Danger)
                        .show_cancel(true),
                )
                .on_ok(move |_, _, cx| {
                    this.update(cx, |this, cx| this.delete_resources(resources.clone(), cx)).ok();
                    true
                })
        });
    }

    /// Deletes `resources` in the background, each row showing a spinner
    /// until it is gone, or says why it couldn't be.
    fn delete_resources(&mut self, resources: Vec<Resource>, cx: &mut Context<Self>) {
        for resource in resources {
            let key = (resource.runtime, resource.id.clone());
            self.delete_errors.remove(&key);
            if !self.deleting.insert(key.clone()) {
                continue;
            }
            let deleted = cx.background_spawn({
                let resource = resource.clone();
                async move { crate::container::delete(&resource).map_err(|err| format!("{err:#}")) }
            });
            self._deletes.push(cx.spawn(async move |this, cx| {
                let deleted = deleted.await;
                this.update(cx, |this, cx| {
                    this.deleting.remove(&key);
                    match deleted {
                        Ok(()) => {
                            if let Some(containers) = &mut this.containers {
                                for (runtime, found) in &mut containers.resources {
                                    if let Ok(found) = found
                                        && *runtime == key.0
                                    {
                                        found.retain(|known| known.id != key.1);
                                    }
                                }
                            }
                        }
                        Err(why) => {
                            this.delete_errors.insert(key, why);
                        }
                    }
                    cx.notify();
                })
                .ok();
            }));
        }
        cx.notify();
    }

