    /// The application's resources are listed by its label and names, each
    /// once, others' left alone, and deleting one runs the runtime's own
    /// removal of it.
    #[cfg(unix)]
    #[test]
    fn resources_are_listed_and_deleted() {
        let dir = std::env::temp_dir().join(format!("suspense-resources-{}", std::process::id()));
        std::fs::remove_dir_all(&dir).ok();
        std::fs::create_dir_all(&dir).unwrap();
        let script = dir.join("podman");
        let log = dir.join("ran");
        std::fs::write(
            &script,
            format!(
                "#!/bin/sh\necho \"$@\" >> {log}\ncase \"$1\" in\n\
                 ps) case \"$5\" in *io.suspense.app*) printf 'c1\\tsuspense-spec-1-0\\tUp 2 minutes\\t1kB (virtual 2GB)\\t2026-10-12 10:00:00 +0700 +07\\n' ;; esac ;;\n\
                 images) printf 'i1\\tlocalhost/suspense-default\\tlatest\\t2.1 GB\\t2026-10-10 19:23:17 +0000 UTC\\ni1\\tlocalhost/suspense-default\\tabc\\t2.1 GB\\t2026-10-10 19:23:17 +0000 UTC\\ni2\\tdocker.io/library/node\\t22\\t300 MB\\t2026-10-01 10:00:00 +0000 UTC\\n' ;;\n\
                 volume) case \"$2\" in ls) printf 'suspense-home-claude\\nsomeone-else\\n' ;; inspect) echo '2026-10-01 10:00:00 +0000 UTC' ;; esac ;;\n\
                 esac\n",
                log = log.display()
            ),
        )
        .unwrap();
        crate::test_scripts::make_executable(&script);
        use_podman_for_test(Some(script));
        let found = super::resources(super::Runtime::Podman).unwrap();
        let listed: Vec<(super::ResourceKind, &str, &str)> =
            found.iter().map(|r| (r.kind, r.name.as_str(), r.purpose.as_str())).collect();
        assert_eq!(
            listed,
            [
                (super::ResourceKind::Container, "suspense-spec-1-0", "Running: Spec task"),
                (super::ResourceKind::Image, "localhost/suspense-default:latest", "Default image"),
                (super::ResourceKind::Volume, "suspense-home-claude", "Claude Code login"),
            ]
        );
        assert_eq!(found[1].size, Some(2_100_000_000));
        for resource in &found {
            super::delete(resource).unwrap();
        }
        use_podman_for_test(None);
        let ran = std::fs::read_to_string(&log).unwrap();
        assert!(ran.contains("rm -f c1") && ran.contains("rmi -f i1") && ran.contains("volume rm -f suspense-home-claude"), "{ran}");
        assert!(!ran.contains("someone-else") || !ran.contains("rm -f someone-else"));
        std::fs::remove_dir_all(&dir).ok();
    }
}
